package io.github.bataokun.augustble

import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.channels.Channel
import kotlinx.coroutines.flow.receiveAsFlow
import kotlinx.coroutines.runBlocking
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test

/**
 * End-to-end protocol test driven by `vectors.json`, which was generated by
 * `tools/gen-vectors.js` simulating both sides of the protocol with Node's
 * crypto (including the stateful CBC chain). If the Kotlin code produces
 * byte-identical wire traffic for the full transcript — handshake, unlock,
 * lock, unlock again, status, disconnect — it matches the fixture.
 */
class AugustLockVectorTest {

    private data class Step(val name: String, val channel: String, val requestHex: String, val responseHex: String)

    private class ScriptedChannel(
        private val name: String,
        responses: List<ByteArray>,
        private val log: MutableList<Pair<String, String>>,
    ) : GattChannel {
        private val pending = ArrayDeque(responses)
        private val out = Channel<ByteArray>(Channel.UNLIMITED)
        override val incoming: Flow<ByteArray> = out.receiveAsFlow()

        override suspend fun write(value: ByteArray) {
            log += name to value.toHexString()
            pending.removeFirstOrNull()?.let { out.trySend(it) }
        }
    }

    private fun loadVectors(): Triple<Map<String, String>, Int, List<Step>> {
        val text = javaClass.getResourceAsStream("/vectors.json")!!.bufferedReader().readText()
        fun field(name: String): String =
            Regex(""""$name"\s*:\s*"([0-9a-f]+)"""").find(text)!!.groupValues[1]
        val offset = Regex(""""offlineKeyOffset"\s*:\s*(\d+)""").find(text)!!.groupValues[1].toInt()
        val stepRegex = Regex(
            """"name"\s*:\s*"([^"]+)".*?"channel"\s*:\s*"([^"]+)".*?"requestPlainHex"\s*:\s*"([0-9a-f]+)".*?"requestHex"\s*:\s*"([0-9a-f]+)".*?"responseHex"\s*:\s*"([0-9a-f]+)"""",
            RegexOption.DOT_MATCHES_ALL,
        )
        val steps = stepRegex.findAll(text).map { m ->
            Step(m.groupValues[1], m.groupValues[2], m.groupValues[4], m.groupValues[5])
        }.toList()
        return Triple(
            mapOf(
                "offlineKeyHex" to field("offlineKeyHex"),
                "handshakeKeysHex" to field("handshakeKeysHex"),
                "sessionKeyHex" to field("sessionKeyHex"),
            ),
            offset,
            steps,
        )
    }

    @Test
    fun `full transcript matches the fixture byte for byte`() = runBlocking {
        val (fields, offset, steps) = loadVectors()
        assertEquals(7, steps.size, "expected the 7-step transcript")

        val log = mutableListOf<Pair<String, String>>()
        fun channel(name: String) = ScriptedChannel(
            name,
            steps.filter { it.channel == name }.map { it.responseHex.hexToBytes() },
            log,
        )

        val lock = AugustLock(
            sessionChannel = channel("session"),
            secureChannel = channel("secure"),
            offlineKey = fields.getValue("offlineKeyHex").hexToBytes(),
            offlineKeyOffset = offset,
            scope = kotlinx.coroutines.CoroutineScope(kotlinx.coroutines.Dispatchers.Unconfined),
            handshakeRandom = { fields.getValue("handshakeKeysHex").hexToBytes() },
        )

        lock.connect()
        assertTrue(lock.isSecure)
        assertEquals(fields.getValue("sessionKeyHex"), lock.sessionKey!!.toHexString())

        lock.unlock()
        lock.lock()
        lock.unlock() // 2nd unlock: catches a broken (non-stateful) CBC implementation
        assertEquals(LockStatus.LOCKED, lock.status())
        lock.disconnect()

        val expected = steps.map { it.channel to it.requestHex }
        assertEquals(expected, log, "wire traffic diverged from the fixture")
    }

    @Test
    fun `same session command encrypts differently the second time (stateful CBC)`() = runBlocking {
        // unlock_1 and unlock_2 have identical plaintext but must differ on the
        // wire; a fresh-IV-per-message port would produce identical bytes and
        // fail against a real lock. This asserts the vectors themselves carry
        // that property so the transcript test above cannot pass vacuously.
        val (_, _, steps) = loadVectors()
        val unlock1 = steps.first { it.name == "unlock_1" }
        val unlock2 = steps.first { it.name == "unlock_2" }
        assertTrue(unlock1.requestHex != unlock2.requestHex)
    }
}
